package thaumcraft.taint;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.tags.BlockTags;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;
import thaumcraft.aura.*;
import thaumcraft.config.ThaumcraftConfig;
public final class TaintWorld{
 private TaintWorld(){}
 public enum Presence{PRESENT,ABSENT,UNKNOWN}
 public static boolean place(ServerLevel l,BlockPos p,BlockPos origin,BlockState next,Player player){if(!l.isInWorldBounds(p)||!l.hasChunkAt(p)||l.getBlockEntity(p)!=null||l.getBlockState(p).getDestroySpeed(l,p)<0)return false;if(player!=null&&(!player.mayBuild()||!l.mayInteract(player,p)||!player.mayUseItemAt(p,Direction.UP,player.getMainHandItem())))return false;var event=new net.minecraftforge.event.level.BlockEvent.FluidPlaceBlockEvent(l,p,origin,next);if(net.minecraftforge.event.level.BlockEvent.FluidPlaceBlockEvent.BUS.post(event))return false;var approved=event.getNewState();return approved.equals(next)&&l.setBlockAndUpdate(p,next);}
 public static TaintedMob seed(ServerLevel l,BlockPos p){int radius=ThaumcraftConfig.taintSpreadArea.get();return l.getEntitiesOfClass(TaintedMob.class,new AABB(p).inflate(radius),e->e.isAlive()&&e.kind.seed&&e.blockPosition().distSqr(p)<=radius*(double)radius).stream().min(Comparator.comparingDouble(e->e.blockPosition().distSqr(p))).orElse(null);}
 public static Presence presence(ServerLevel l,BlockPos p){if(seed(l,p)!=null)return Presence.PRESENT;int r=ThaumcraftConfig.taintSpreadArea.get();for(int x=(p.getX()-r)>>4;x<=(p.getX()+r)>>4;x++)for(int z=(p.getZ()-r)>>4;z<=(p.getZ()+r)>>4;z++)if(!l.hasChunk(x,z))return Presence.UNKNOWN;return Presence.ABSENT;}
 public static boolean taint(BlockState s){return s.getBlock() instanceof TaintBlock||s.is(TaintContent.GOO.get());}
 public static boolean solidNeighbour(ServerLevel l,BlockPos p,boolean normal){for(var d:Direction.values()){var q=p.relative(d);if(!l.hasChunkAt(q))continue;var s=l.getBlockState(q);if(s.isFaceSturdy(l,q,d.getOpposite())&&(!normal||!taint(s)))return true;}return false;}
 public static boolean hemmed(ServerLevel l,BlockPos p){int n=0;for(var d:Direction.values()){var q=p.relative(d);if(!l.hasChunkAt(q))return false;var s=l.getBlockState(q);if(taint(s))n++;else if(s.isAir()||s.getFluidState().isEmpty()&&!s.isFaceSturdy(l,q,d.getOpposite()))n--;}return n>0;}
 public static boolean spread(ServerLevel l,BlockPos from,boolean force){if(!l.hasChunkAt(from)||ThaumcraftConfig.wussMode.get()||ThaumcraftConfig.taintSpreadRate.get()<=0||!l.getGameRules().get(net.minecraft.world.level.gamerules.GameRules.MOB_GRIEFING))return false;var seed=seed(l,from);if(seed==null||!seed.supported())return false;var aura=AuraManager.get(l,from);if(aura==null)return false;if(!force&&l.getRandom().nextDouble()>TaintRules.spreadChance(ThaumcraftConfig.taintSpreadRate.get(),aura.flux(),aura.base()))return false;var p=from.offset(l.getRandom().nextInt(3)-1,l.getRandom().nextInt(3)-1,l.getRandom().nextInt(3)-1);return infect(l,from,p,seed);}
 public static boolean infect(ServerLevel l,BlockPos origin,BlockPos p,TaintedMob seed){if(!l.hasChunkAt(p)||l.getBlockEntity(p)!=null||seed==null||!seed.isAlive()||!seed.kind.seed||seed.blockPosition().distSqr(p)>thaumcraft.config.ThaumcraftConfig.taintSpreadArea.get()*(double)thaumcraft.config.ThaumcraftConfig.taintSpreadArea.get())return false;var s=l.getBlockState(p);float hardness=s.getDestroySpeed(l,p);if(hardness<0||hardness>10||!s.getFluidState().isEmpty())return false;BlockState next=null;
  if(s.is(BlockTags.LEAVES)){next=state("taint_fibre");for(var d:Direction.values())if(l.hasChunkAt(p.relative(d))&&l.getBlockState(p.relative(d)).is(TaintContent.BLOCKS.get("taint_log").get())&&l.getRandom().nextFloat()<.6F){next=state("taint_feature").setValue(TaintBlock.FACING,d.getOpposite());break;}}
  else if((s.isAir()||s.canBeReplaced())&&solidNeighbour(l,p,true))next=state("taint_fibre");
  else if(!taint(s)&&hardness<5&&hemmed(l,p)){if(s.is(BlockTags.LOGS))next=state("taint_log").setValue(TaintBlock.AXIS,s.hasProperty(TaintBlock.AXIS)?s.getValue(TaintBlock.AXIS):Direction.Axis.Y);else if(s.is(BlockTags.PLANKS)||s.is(Blocks.RED_MUSHROOM_BLOCK)||s.is(Blocks.BROWN_MUSHROOM_BLOCK)||s.is(Blocks.PUMPKIN)||s.is(Blocks.MELON)||s.is(Blocks.CACTUS)||s.is(Blocks.SPONGE))next=state("taint_crust");else if(s.is(BlockTags.DIRT)||s.is(BlockTags.SAND)||s.is(Blocks.CLAY)||s.is(Blocks.GRAVEL))next=state("taint_soil");else if(s.is(BlockTags.BASE_STONE_OVERWORLD)||s.is(BlockTags.BASE_STONE_NETHER)||s.is(BlockTags.STONE_BRICKS)||s.is(Blocks.COBBLESTONE))next=state("taint_rock");}
  if(next!=null){if(next.getBlock() instanceof TaintBlock.Fibre f)next=f.connections(l,p,next);if(!place(l,p,origin,next,null))return false;if(!s.is(BlockTags.LOGS))AuraManager.drainFlux(l,p,.01F,false);return true;}
  if((s.is(TaintContent.BLOCKS.get("taint_soil").get())||s.is(TaintContent.BLOCKS.get("taint_rock").get()))&&l.hasChunkAt(p.above())&&l.getBlockState(p.above()).isAir()&&TaintRules.seedEdge(seed.blockPosition().distSqr(p),ThaumcraftConfig.taintSpreadArea.get())&&AuraManager.drainFlux(l,p,5,true)==5&&l.getRandom().nextFloat()<ThaumcraftConfig.taintSpreadRate.get()/100*.33){if(spawnSeed(l,p.above(),false,0)!=null){AuraManager.drainFlux(l,p,5,false);return true;}}return false;
 }
 public static BlockState state(String id){return TaintContent.BLOCKS.get(id).get().defaultBlockState();}
 public static TaintedMob spawnSeed(ServerLevel l,BlockPos p,boolean prime,int boost){if(ThaumcraftConfig.wussMode.get()||l.getDifficulty()==net.minecraft.world.Difficulty.PEACEFUL||!l.hasChunkAt(p)||!l.getBlockState(p).canBeReplaced()||!l.hasChunkAt(p.below())||!l.getBlockState(p.below()).isFaceSturdy(l,p.below(),Direction.UP))return null;int radius=ThaumcraftConfig.taintSpreadArea.get();if(!l.getEntitiesOfClass(TaintedMob.class,new AABB(p).inflate(radius*.8),e->e.isAlive()&&e.kind.seed&&e.blockPosition().distSqr(p)<radius*.8*(radius*.8)).isEmpty())return null;var m=new TaintedMob(TaintContent.MOBS.get(prime?TaintedMob.Kind.PRIME:TaintedMob.Kind.SEED).get(),l,prime?TaintedMob.Kind.PRIME:TaintedMob.Kind.SEED);m.setPos(p.getX()+.5,p.getY(),p.getZ()+.5);m.boost=Math.clamp(boost,0,1200);m.setPersistenceRequired();return l.noCollision(m)&&l.addFreshEntity(m)?m:null;}
}
